data.code:
interface Node { id: ID! }

type User implements Node {
  id: ID!
  name: String!
  email: String           # nullable: pode ser oculto por privacidade
  role: Role!
}

enum Role { ADMIN EDITOR VIEWER }

union SearchResult = User | Post | Tag

type Query {
  posts(first: Int, after: String): PostConnection!
}

type PostConnection {
  edges: [PostEdge!]!
  pageInfo: PageInfo!
  totalCount: Int
}

type PostEdge {
  cursor: String!
  node: Post!
}

type PageInfo {
  hasNextPage: Boolean!
  hasPreviousPage: Boolean!
  startCursor: String
  endCursor: String
}

input CreatePostInput {
  title: String!
  body: String!
  tags: [String!] = []
}

type CreatePostPayload {
  post: Post
  errors: [UserError!]!
}

type UserError { field: [String!]! message: String! code: String! }
